{"path": "src/ready-weapon-truth.mjs", "ref": "a8e96f7959a1087d8d32b6d94b57436e8045026c", "truncated": false, "content": "export function weaponTruthWorldPosition(THREE, node) {
  return node.getWorldPosition(new THREE.Vector3());
}

export function weaponTruthWorldQuaternion(THREE, node) {
  return node.getWorldQuaternion(new THREE.Quaternion()).normalize();
}

export function weaponTruthWorldDirection(THREE, node, axis = [0, 0, 1]) {
  return new THREE.Vector3(...axis).normalize().applyQuaternion(weaponTruthWorldQuaternion(THREE, node)).normalize();
}

export function updateSyntheticWeaponSocketTransform(THREE, { model, root, rightHand, leftHand = null, sourceSocket = null, config = {}, activeClipHasSocketRotation = false } = {}) {
  if (!model || !root) return null;
  if (sourceSocket) {
    root.position.set(0, 0, 0);
    if (Array.isArray(config.modelLocalOffset)) root.position.add(new THREE.Vector3().fromArray(config.modelLocalOffset));
    if (Array.isArray(config.gripOffset)) root.position.add(new THREE.Vector3().fromArray(config.gripOffset));
    return { socketUpdated: true, sourceSocket: true, copiedHandQuaternion: false };
  }
  if (!rightHand) return null;
  model.updateMatrixWorld(true);
  const rightWorld = Array.isArray(config.handLocalOffset)
    ? rightHand.localToWorld(new THREE.Vector3().fromArray(config.handLocalOffset))
    : weaponTruthWorldPosition(THREE, rightHand);
  const leftWorld = leftHand ? weaponTruthWorldPosition(THREE, leftHand) : rightWorld;
  const socketWorld = (config.positionMode || 'two-hand-center') === 'right-hand'
    ? rightWorld.clone()
    : rightWorld.clone().add(leftWorld).multiplyScalar(0.5);
  const local = model.worldToLocal(socketWorld.clone());
  if (Array.isArray(config.modelLocalOffset)) local.add(new THREE.Vector3().fromArray(config.modelLocalOffset));
  if (Array.isArray(config.gripOffset)) local.add(new THREE.Vector3().fromArray(config.gripOffset));
  root.position.copy(local);
  let copiedHandQuaternion = false;
  if (!activeClipHasSocketRotation) {
    const modelWorldQuat = weaponTruthWorldQuaternion(THREE, model).invert();
    root.quaternion.copy(modelWorldQuat.multiply(weaponTruthWorldQuaternion(THREE, rightHand))).normalize();
    copiedHandQuaternion = true;
  }
  model.updateMatrixWorld(true);
  return { socketUpdated: true, sourceSocket: false, copiedHandQuaternion };
}

export function applyWeaponAttachmentTruthTransform(THREE, { weaponRoot, tip = null, config = {}, fallbackTipOffset = [0, 0, 0.85], boneRest = null } = {}) {
  if (!weaponRoot || !config) return null;
  weaponRoot.scale.setScalar(Number(config.scale ?? 1));
  if (Array.isArray(config.rotationDeg)) weaponRoot.rotation.set(...config.rotationDeg.map((value) => THREE.MathUtils.degToRad(value || 0)));
  if (Array.isArray(config.position)) weaponRoot.position.fromArray(config.position);
  else weaponRoot.position.set(0, 0, 0);
  if (Array.isArray(config.gripLocalPosition)) {
    const localGrip = new THREE.Vector3().fromArray(config.gripLocalPosition);
    localGrip.multiplyScalar(Number(config.scale ?? 1));
    localGrip.applyQuaternion(weaponRoot.quaternion);
    weaponRoot.position.sub(localGrip);
  }
  if (tip) {
    if (Array.isArray(config.tipLocalPosition)) {
      const localTip = new THREE.Vector3().fromArray(config.tipLocalPosition);
      localTip.multiplyScalar(Number(config.scale ?? 1));
      localTip.applyQuaternion(weaponRoot.quaternion);
      localTip.add(weaponRoot.position);
      tip.position.copy(localTip);
    } else {
      tip.position.fromArray(config.tipOffset || fallbackTipOffset);
    }
    const rest = boneRest?.get?.(tip.name);
    if (rest) rest.position.copy(tip.position);
  }
  return { attachmentUpdated: true };
}

export function classifyWeaponVisibility({ clipName = '', clipUserData = {}, config = {}, weaponDebug = false } = {}) {
  const patterns = config.visibleClipPatterns || ['\\[FPS-SWORD-UPPER\\]', 'OneHand'];
  const matchedPattern = patterns.find((pattern) => new RegExp(pattern).test(clipName || '')) || '';
  const visible = Boolean(weaponDebug || clipUserData?.weaponPathIk || matchedPattern);
  const reasons = [];
  if (weaponDebug) reasons.push('weapon-debug-forced-visible');
  if (clipUserData?.weaponPathIk) reasons.push('clip-userdata-weaponPathIk');
  if (matchedPattern) reasons.push(`visible-pattern:${matchedPattern}`);
  if (!visible) reasons.push('runtime-visibility-hidden');
  return {
    visible,
    visibilityClass: visible ? 'weapon-visible' : 'weapon-hidden',
    matchedPattern,
    patterns,
    reasons,
  };
}

export function measureReadyWeaponTruth(THREE, { socket, rightHand, weaponRoot = null, tip = null, attachmentConfig = {} } = {}) {
  if (!socket || !rightHand) return null;
  socket.updateMatrixWorld(true);
  rightHand.updateMatrixWorld(true);
  weaponRoot?.updateMatrixWorld?.(true);
  tip?.updateMatrixWorld?.(true);
  const hilt = weaponTruthWorldPosition(THREE, socket);
  const hand = weaponTruthWorldPosition(THREE, rightHand);
  let tipWorld = tip ? weaponTruthWorldPosition(THREE, tip) : null;
  if (!tipWorld && weaponRoot && Array.isArray(attachmentConfig.tipLocalPosition)) {
    const localTip = new THREE.Vector3().fromArray(attachmentConfig.tipLocalPosition);
    localTip.multiplyScalar(Number(attachmentConfig.scale ?? 1));
    localTip.applyQuaternion(weaponRoot.quaternion);
    localTip.add(weaponRoot.position);
    tipWorld = socket.localToWorld(localTip.clone());
  }
  if (!tipWorld) tipWorld = hilt.clone().add(weaponTruthWorldDirection(THREE, socket, [0, 0, 1]));
  const bladeAxis = tipWorld.clone().sub(hilt);
  if (bladeAxis.lengthSq() > 1e-9) bladeAxis.normalize();
  return {
    hilt,
    hand,
    tip: tipWorld,
    bladeAxis,
    socketForward: weaponTruthWorldDirection(THREE, socket, [0, 0, 1]),
    socketQuaternion: weaponTruthWorldQuaternion(THREE, socket),
    handQuaternion: weaponTruthWorldQuaternion(THREE, rightHand),
    hiltToHandDistance: hilt.distanceTo(hand),
  };
}

export function classifyReadyWeaponTransform(THREE, { readyState, restState, maxHiltToHand = 0.18, minBladeAxisChangeDeg = 20, maxSocketHandQuaternionErrorDeg = 0.5 } = {}) {
  if (!readyState || !restState) return { transformClass: 'unknown', reasons: ['missing-state'] };
  const bladeAxisChangeDeg = THREE.MathUtils.radToDeg(restState.bladeAxis.clone().normalize().angleTo(readyState.bladeAxis.clone().normalize()));
  const socketHandQuaternionErrorDeg = THREE.MathUtils.radToDeg(readyState.socketQuaternion.angleTo(readyState.handQuaternion));
  const follows = readyState.hiltToHandDistance <= maxHiltToHand
    && bladeAxisChangeDeg >= minBladeAxisChangeDeg
    && socketHandQuaternionErrorDeg <= maxSocketHandQuaternionErrorDeg;
  const reasons = [];
  if (readyState.hiltToHandDistance > maxHiltToHand) reasons.push('hilt-far-from-hand');
  if (bladeAxisChangeDeg < minBladeAxisChangeDeg) reasons.push('blade-rest-space');
  if (socketHandQuaternionErrorDeg > maxSocketHandQuaternionErrorDeg) reasons.push('socket-not-hand-frame');
  return {
    transformClass: follows ? 'sword-follows-fk' : 'sword-rest-space',
    reasons,
    metrics: {
      hiltToHandDistance: Number(readyState.hiltToHandDistance.toFixed(5)),
      bladeAxisChangeFromRestDeg: Number(bladeAxisChangeDeg.toFixed(2)),
      socketToHandQuaternionErrorDeg: Number(socketHandQuaternionErrorDeg.toFixed(3)),
    },
  };
}

export function classifyReadyWeaponTruth(THREE, { readyState, restState, visibility = null } = {}) {
  const transform = classifyReadyWeaponTransform(THREE, { readyState, restState });
  const visible = visibility?.visible !== false;
  const reasons = [...(transform.reasons || [])];
  if (!visible) reasons.push('weapon-not-visible-in-runtime');
  return {
    visualClass: visible ? transform.transformClass : 'sword-hidden',
    transformClass: transform.transformClass,
    visibilityClass: visibility?.visibilityClass || (visible ? 'weapon-visible' : 'weapon-hidden'),
    reasons,
    metrics: transform.metrics,
    visibility,
  };
}

export function buildReadyWeaponParityVerdict({ observedWebClass, offlineClass }) {
  const parityMatches = Boolean(observedWebClass && offlineClass && observedWebClass === offlineClass);
  return {
    parityMatches,
    visualVerdict: parityMatches && observedWebClass === 'sword-follows-fk' ? 'fixed' : 'red',
    parityFailure: parityMatches ? '' : 'offline-web-visual-class-diverged',
  };
}
"}

{"path": "tools/pose_lab_workflow_lib.mjs", "ref": "a8e96f7959a1087d8d32b6d94b57436e8045026c", "truncated": false, "content": "import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

export const projectRoot = path.resolve(import.meta.dirname, '..');
export const baselinePath = path.join(projectRoot, 'generated', 'workflow_state', 'meshy_fps_accepted_baseline.json');
export const latestEvidencePath = path.join(projectRoot, 'generated', 'visual_red_build', 'meshy_ready_weapon_fk_follow_latest.json');

export function readJson(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

export function readText(relativePath) {
  return fs.readFileSync(path.join(projectRoot, relativePath), 'utf8');
}

export function currentCacheToken() {
  const html = readText('pose-lab.html');
  const match = html.match(/pose-lab\.js\?v=([^'"\s]+)/);
  return match?.[1] || '';
}

export function currentRuntimeBuild() {
  const runtime = readText('src/pose-lab.js');
  const match = runtime.match(/const\s+LAB_BUILD\s*=\s*['"]([^'"]+)['"]/);
  return match?.[1] || '';
}

export function currentCommit() {
  try {
    return execFileSync('git', ['-c', `safe.directory=${projectRoot}`, 'rev-parse', '--short', 'HEAD'], { cwd: projectRoot, encoding: 'utf8' }).trim();
  } catch (_err) {
    return '';
  }
}

export function gitStatusLines() {
  try {
    return execFileSync('git', ['-c', `safe.directory=${projectRoot}`, 'status', '--short'], { cwd: projectRoot, encoding: 'utf8' })
      .split(/\r?\n/)
      .map((line) => line.trimEnd())
      .filter(Boolean);
  } catch (_err) {
    return [];
  }
}

export function protectedDirtyFiles(lines = gitStatusLines()) {
  const protectedPrefixes = [
    'PROJECT_ORIENTATION.md',
    'docs/ANIMATION_WORKFLOW_TOOLING.md',
    'pose-critique.html',
    'pose-lab.html',
    'src/pose-lab.js',
    'src/rig-profiles.js',
    'generated/workflow_state/',
    'tools/promote_pose_candidate.mjs',
    'tools/pose_lab_workflow_status.mjs',
    'tools/pose_lab_workflow_lib.mjs',
  ];
  return lines.filter((line) => {
    const file = line.replace(/^.. /, '');
    return protectedPrefixes.some((prefix) => file === prefix || file.startsWith(prefix));
  });
}

export function currentMeshySelectionSurfaces() {
  const profiles = readText('src/rig-profiles.js');
  const meshyStart = profiles.indexOf('meshyCharacter:');
  const meshyEnd = profiles.indexOf('\n  meshyStatic:', meshyStart);
  const meshy = profiles.slice(meshyStart, meshyEnd > meshyStart ? meshyEnd : undefined);
  const startupClip = meshy.match(/startupClip:\s*\{\s*name:\s*'([^']+)'/)?.[1] || '';
  const lineFor = (name) => meshy.split(/\r?\n/).find((line) => line.includes(`${name}: [`)) || '';
  const stringValues = (line) => Array.from(line.matchAll(/'((?:\\'|[^'])*)'|"((?:\\"|[^"])*)"/g))
    .map((entry) => (entry[1] ?? entry[2] ?? '').replace(/\\\\/g, '\\').replace(/\\'/g, "'").replace(/\\"/g, '"'));
  return {
    startupClip,
    swordReadyAliases: stringValues(lineFor('SwordReady')),
    restProbeAliases: stringValues(lineFor('RestProbe')),
    weaponVisibleClipPatterns: stringValues(lineFor('visibleClipPatterns')),
  };
}

export function compareSelectionSurfaces(baseline, current = currentMeshySelectionSurfaces()) {
  const expected = baseline.selectionSurfaces || {};
  const mismatches = [];
  for (const key of ['startupClip', 'swordReadyAliases', 'restProbeAliases', 'weaponVisibleClipPatterns']) {
    const a = JSON.stringify(expected[key] ?? (Array.isArray(current[key]) ? [] : ''));
    const b = JSON.stringify(current[key] ?? (Array.isArray(expected[key]) ? [] : ''));
    if (a !== b) mismatches.push({ key, expected: expected[key], actual: current[key] });
  }
  return mismatches;
}

export function evidenceCacheToken(evidence) {
  return evidence.cacheToken || evidence.currentFixCacheToken || '';
}

export function evidenceClipName(evidence) {
  return evidence.clipName || evidence.readyClipName || '';
}

export function isParityEvidence(evidence) {
  return evidence?.schema === 'pose-lab-ready-weapon-fk-offline-web-parity-gate-v1';
}

export function isLegacyVisualEvidence(evidence) {
  return evidence?.schema === 'pose-lab-visual-evidence-v1';
}


export function resolveEvidencePath(file) {
  if (!file) return '';
  return path.isAbsolute(file) ? file : path.join(projectRoot, file);
}

function jsonEqual(a, b) {
  return JSON.stringify(a) === JSON.stringify(b);
}

function readEvidenceJsonForValidation(file, label, errors) {
  const resolved = resolveEvidencePath(file);
  if (!file) {
    errors.push(`parity evidence missing ${label}`);
    return null;
  }
  if (!fs.existsSync(resolved)) {
    errors.push(`parity evidence ${label} does not exist: ${file}`);
    return null;
  }
  try {
    return readJson(resolved);
  } catch (error) {
    errors.push(`parity evidence ${label} is invalid JSON: ${error.message}`);
    return null;
  }
}

export function validateParityEvidenceReadback(evidence) {
  const errors = [];
  if (!isParityEvidence(evidence)) return errors;
  const observed = readEvidenceJsonForValidation(evidence.observedWebTruthPath, 'observedWebTruthPath', errors);
  if (observed && !jsonEqual(observed, evidence.observedWebTruth)) {
    errors.push('parity evidence embedded observedWebTruth does not match observedWebTruthPath file');
  }
  const offlineArtifactPath = evidence.offlineVisualTruth?.artifactPath || '';
  const offline = readEvidenceJsonForValidation(offlineArtifactPath, 'offlineVisualTruth.artifactPath', errors);
  if (offline) {
    for (const key of ['cacheToken', 'runtimeBuild', 'actorKey', 'clipName', 'observedWebTruthPath', 'result']) {
      if (!jsonEqual(offline[key], key === 'result' ? evidence.offlineVisualTruth?.result : evidence[key])) {
        errors.push(`parity evidence offline artifact ${key} does not match wrapper`);
      }
    }
    for (const key of ['observedWebTruth', 'offlineTruth', 'parity']) {
      if (!jsonEqual(offline[key], evidence[key])) errors.push(`parity evidence offline artifact ${key} does not match wrapper`);
    }
    if (!jsonEqual(offline.sheet, evidence.offlineVisualTruth?.sheetPath)) {
      errors.push('parity evidence offline artifact sheet does not match wrapper sheetPath');
    }
  }
  const sheetPath = evidence.offlineVisualTruth?.sheetPath || '';
  const resolvedSheet = resolveEvidencePath(sheetPath);
  if (!sheetPath) {
    errors.push('parity evidence missing offlineVisualTruth.sheetPath');
  } else if (!fs.existsSync(resolvedSheet)) {
    errors.push(`parity evidence sheetPath does not exist: ${sheetPath}`);
  } else if (fs.statSync(resolvedSheet).size <= 0) {
    errors.push(`parity evidence sheetPath is empty: ${sheetPath}`);
  }
  return errors;
}

export function latestEvidenceStatus(file = latestEvidencePath) {
  if (!fs.existsSync(file)) return { exists: false, path: file, stale: true, blocked: true, errors: ['missing visual evidence'] };
  let evidence = null;
  try {
    evidence = readJson(file);
  } catch (error) {
    return { exists: true, path: file, stale: true, blocked: true, errors: [`invalid evidence JSON: ${error.message}`] };
  }
  const cacheToken = [REDACTED]
  const runtimeBuild = currentRuntimeBuild();
  const errors = [];
  const token = [REDACTED]
  if (token !== cacheToken) errors.push(`evidence cacheToken ${token || 'missing'} != current ${cacheToken || 'missing'}`);
  if (evidence.runtimeBuild !== runtimeBuild) errors.push(`evidence runtimeBuild ${evidence.runtimeBuild || 'missing'} != current ${runtimeBuild || 'missing'}`);
  if (isParityEvidence(evidence)) {
    if (evidence.browserCaptureDeprecated !== true) errors.push('parity evidence must deprecate browser capture');
    if (evidence.parity?.visualVerdict !== 'fixed') errors.push(`parity evidence is ${evidence.parity?.visualVerdict || 'missing'}, not fixed`);
    errors.push(...validateParityEvidenceReadback(evidence));
  } else if (isLegacyVisualEvidence(evidence)) {
    if (evidence.liveVisualQa?.status === 'blocked' || evidence.captureKind === 'visual-qa-blocked') errors.push('evidence is blocked');
    if (evidence.motionEvidencePending === true) errors.push('motion evidence is pending');
  } else {
    errors.push(`visual evidence schema ${evidence.schema || 'missing'} is unsupported`);
  }
  return {
    exists: true,
    path: file,
    evidence,
    stale: token !== cacheToken || evidence.runtimeBuild !== runtimeBuild,
    blocked: isParityEvidence(evidence) ? evidence.parity?.visualVerdict !== 'fixed' || errors.length > 0 : evidence.liveVisualQa?.status === 'blocked' || evidence.captureKind === 'visual-qa-blocked',
    errors,
  };
}

